        description='你触碰一名已死，但死亡时间不超过10日，且死亡时并非亡灵Undead的生物，使其回生。生物以1点生命值重生。该法术同样会中和在该生物死亡时仍在生效的毒素。该法术能治愈所有致命伤，但无法恢复失去的身体部位。如果该生物缺失了它生存所必要的身体部位或器官（比如头），则该法术自动失败。死而复生是一个痛苦的体验。目标进行D20检定时具有-4减值。目标每完成一次长休，其减值就减少1，直至减值变为0',
