        description='你获得以思想移动或操纵生物或物件的能力。当你施展该法术时或于该法术终止前，你在法术施展之后的回合中都可以用一个魔法动作，将你的意志强加于施法距离内你可见的一名生物或一个物件之上，并造成下述对应的效应。你可以一轮接一轮地影响同一个目标，也可以在任何时候选择一个新的目标。如果你改变了目标，则之前的目标将不再受该法术影响。 生物Creature。你可以尝试移动一名巨型或更小的生物。目标必须成功于一次力量豁免，否则你可以在施法范围内将其往任意方向移动至多30尺。在你的下个回合结束前，该生物陷入束缚状态，而被你举到空中的生物会在半空中悬停。除非你再次对该被举到空中的生物使用此选项且其失败于豁免，否则其会在你的下个回合结束时坠落。物件Object。你可以尝试移动一个巨型或更小的物件。如果该物品没有被着装或携带，则你可以自动使它在施法范围内朝任何方向移动至多30尺。如果该物件已被一名生物着装或携带，则该生物必须成功于一次力量豁免，否则你可以把目标物件从该生物身上驱离，并且使该物体在施法范围内朝任意方向移动至多30尺。你可以使用心灵遥控对物件进行精密操作，例如操纵一件简单的工具，打开一扇门或一个...',
