        description='一名施法距离内你可见的生物必须进行一次感知豁免，豁免成功则目标直到其下个回合结束为止会跳起滑稽的舞蹈，在此期间其必须消耗所有的移动力在原地跳舞。若豁免失败，目标将在法术持续时间内陷入魅惑状态。处于魅惑状态期间，目标会跳起滑稽的舞蹈，必须使用所有的移动力在原地跳舞，并且进行的敏捷豁免与攻击检定具有劣势，且其他生物以该生物为目标发动的攻击检定具有优势。在目标的每个自己的回合，它可以用一个动作尝试使自己镇定下来并重复豁免，豁免成功则其身上的法术终止',
