        ac_bonus=0,
        upcast=None,
        description='你祈求一名异界实体的援助。你必须对该存在有所了解，它可以是一位神祇，一名恶魔主君，或是其他拥有宇宙级伟力的存在。该实体将派遣一名效忠它的天族生物，元素生物或邪魔生物来援助你，并使该生物显现在施法距离内一处未占空间。如果你知道某个特定生物的名字，则你可以在施展法术时说出其名字来请求指派该生物来援，但是你仍然有可能得到一名不同的生物（由DM选择）。该生物出现时，它并未被强迫做任何事。你可以用报酬为交换，请求其提供服务，但它并没有为你实现请求的义务。请求的任务可以简单（帮我们飞越峡谷，或协助我们进行一场战斗），也可以复杂（暗中监视我们的敌人，或在我们扫荡地城时保护我们）。你必须能与该生物交流从而为其服务讨价还价。报酬的形式各式各样。一名天族可能会要求为一座同盟的神殿捐献一份相当可观的金币或魔法物品，而一只邪魔可能会索要一次活祭或一份财宝作为礼物。一些生物可能会要求你进行一个任务来换取它们的服务。一个可以按分钟计算的任务需要每分钟100GP的报酬。一个可以按小时计算的任务需要每小时1000GP的报酬。一个可以按日计算的任务（至多10日）需要每日10000GP  的报酬。DM可以按你施展该...',
