        description='你在施法距离内一块坚实的地面上创造出一面冰墙。你可以将它塑成半球状或球状（半径最长10尺），也可以塑成一个由十个10尺×10尺的方板块构成的平面。每块板块都必须要和至少一块其他板块相连。不管形状如何，冰墙总是厚1尺并持续存在至法术终止。如果冰墙形成时穿过了某生物所占据的空间，则该生物会被推到冰墙的一侧（由你来决定是哪一侧）且必须进行一次敏捷豁免。豁免失败，受到10d6点寒冷伤害。豁免成功，则只受一半伤害。作为一个物件，冰墙可以因受到伤害而被打破。冰墙的AC为12，每段10尺长的冰墙有30点生命值，而且冰墙具有寒冷、毒素和心灵伤害的免疫，以及火焰伤害的易伤。当一段10尺长的冰墙的生命值降至0时，这段冰墙就会被摧毁，但原地会留下一片冰冷刺骨的空气。生物在一个回合内第一次通过这片寒气时，必须进行一次体质豁免。豁免失败，受到5d6点寒冷伤害。豁免成功，则只受一半伤害',
