        description='一束黄光从你的指尖射向施法距离内你指定的一点，并在法术持续时间内在该点凝结成一颗珠子。法术终止时，珠子将伴着低吼炸裂成四窜的烈焰，位于目标点半径20尺球状区域内的每名生物都必须进行一次敏捷豁免。豁免失败者将承受全部累积的火焰伤害，豁免成功则只受到一半伤害。该法术的基础伤害为12d6，且若在你回合结束时法术尚未终止，则其伤害增加1d6。如果珠子爆炸前被生物触碰到，则该生物必须进行一次敏捷豁免。豁免失败则法术立即终止并触发爆炸效应。豁免成功则该生物可将珠子抛开至多40尺。当珠子进入一名生物的空间或撞到某个固态物件时，法术立即终止并且触发爆炸效应。珠子爆炸时，区域内未被着装或携带的可燃物件会开始燃烧',
