        upcast=None,
        description='你围绕施法距离内一处指定地点力场构筑出一个固定的立方状隐形Invisible监牢。你可以选择监牢的形式为笼状或盒状。笼状监牢为各边长至多20尺的立方体，其墙体由1/2寸粗的力场栅栏杆组成，每根杆子之间相距1/2寸。盒状监牢为各边长至多10尺的立方体，其墙体为由力场墙密封，并阻隔一切物质进出，也会阻挡任何从区域中向外界施展或从外界向区域中施展的法术。施展该法术时，所有完全在法术区域内的生物将被牢笼困住。部分处于区域内或者体型比区域更大的生物则被从区域中心向外推开，直至其完全离开该区域。牢笼内的生物不能以非魔法的手段离开。如果该生物试图使用传送或跨位面旅行来离开牢笼，则其必须先进行一次魅力豁免。豁免成功则该生物可以用该魔法离开牢笼。豁免失败者将无法以此离开牢笼并浪费掉该法术或效应。该牢笼同时延伸至以太位面Ethereal  Plane 从而屏蔽途经以太位面的旅行。该法术不能被解除魔法Dispel  Magic 解除',
