        description='你在施法距离内召唤一扇微微发光的门，并维持至法术持续时间结束。门宽5尺，高10尺，指向一个异次元居所。只要该门保持开启，你和你施展该法术时指定的任意生物都可以进入该异次元居所中。你可以在距该门不超过 30 尺处开启或关闭之（无需动作）。门在关闭状态下其无法被发现。门的另一侧是一个连接着众多房间的华丽大厅。整个居所的空气洁净清新而温暖舒适。你可以随意创造自己喜欢的房间构造，但不得超出50个相连的边长10尺的立方体。空间内依你喜好配置好家具和装饰，其内储备的食材足以制作供至多100人享用的九菜大宴。由该法术创造的家具和其他物品如果被移出豪宅，就会化作烟雾消散。一组共100名的近乎透明的仆从会招待任何进入房间的人。仆从的外貌着装由你决定，它们无法受伤并服从你的命令。每个仆从都可以完成一个普通人程度的工作，但它们不能攻击或者进行任何直接伤害其他生物的行动。因而仆从可以完成的工作包括：取来物品、清洁、修理、叠衣服、生火、上菜、倒酒等等。仆从不能离开该居所。该法术终止时，任何仍处于该异次元空间内的生物或物件都将被移出空间内，并出现在距离入口最近未被占据的空间内',
