        description='你在法术持续时间内操控距你5里内的天气。你在施法时必须位于户外，并且若你回到室内，法术会提前终止。你施展此法术时，可以改变现有的天气状况（由DM决定）。你可以改变降水、气温和风势。新状况需要1d4×10分钟才能起效。一旦新状况起效，你便能再次改变天气状况。法术结束时，天气状况会逐渐回归正常。改变天气状况时，你可以从下述表格查明与目前状况对应的等级，再选择同一表格中高一级或低一级的状况作为其改变结果。改变风势时，你还可以同时改变其风向。  降水Precipitation  气温Temperature  风势Wind  阶段  状况  阶段  状况  阶段  状况  1  晴  1  酷热  1  无风  2  薄云  2  炎热  2  和风  3  多云或有雾  3  温暖  3  强风  4  雨、雹或雪  4  凉爽  4  大风  5  倾盆大雨、猛烈冰雹或漫天暴雪  5  寒冷  5  暴风  6  极寒',
